      li.addEventListener("dragleave", () => li.classList.remove("is-over"));
      li.addEventListener("drop", (e) => { e.preventDefault(); li.classList.remove("is-over"); });
    });
  };

  // touch / pointer reorder
  const bindTouch = (ul) => {
    let active = null, placeholder = null;
    const onDown = (e) => {
      const li = e.target.closest("li.disc-item");
      if (!li || li.parentElement !== ul) return;
      if (e.pointerType === "mouse") return;
      active = li;
      li.classList.add("is-dragging");
      ul.classList.add("is-reordering");
      li.setPointerCapture && li.setPointerCapture(e.pointerId);
      e.preventDefault();
    };
    const onMove = (e) => {
      if (!active) return;
      const under = document.elementFromPoint(e.clientX, e.clientY);
      const target = under && under.closest && under.closest("li.disc-item");
      if (!target || target === active || target.parentElement !== ul) return;
      const r = target.getBoundingClientRect();
      const before = e.clientY - r.top < r.height / 2;
      ul.insertBefore(active, before ? target : target.nextSibling);
    };
    const onUp = () => {
      if (!active) return;
      active.classList.remove("is-dragging");
      ul.classList.remove("is-reordering");
      active = null;
    };
    ul.addEventListener("pointerdown", onDown);
    ul.addEventListener("pointermove", onMove);
    ul.addEventListener("pointerup", onUp);
    ul.addEventListener("pointercancel", onUp);
  };

  const initLists = () => {
    qsa(".disc-list", wizard).forEach(ul => { bindSortable(ul); bindTouch(ul); });
  };

  // ---------- wizard ----------
  const render = () => {
    tabs.forEach(t => {
      const on = Number(t.dataset.stepBtn) === step;
      t.classList.toggle("is-active", on);
      t.setAttribute("aria-selected", on ? "true" : "false");
    });
    qsa("[data-step-pane]", wizard).forEach(p =>
      p.classList.toggle("is-active", Number(p.dataset.stepPane) === step));
    btnPrev.disabled = step === 0;
    btnNext.classList.toggle("hidden", step === STEPS - 1);
    btnFinish.classList.toggle("hidden", step !== STEPS - 1);
    progressEl.style.width = ((step + 1) / STEPS * 100) + "%";
    qs(".disc-modal__body", wizard).scrollTop = 0;
  };
  const setStep = (n) => { step = Math.max(0, Math.min(STEPS - 1, n)); render(); };

  const openWizard = () => {
    wizard.classList.add("is-open");
    wizard.setAttribute("aria-hidden", "false");
    document.body.classList.add("no-scroll");
    document.documentElement.classList.add("no-scroll");
    render();
  };
  const closeWizard = () => {
    wizard.classList.remove("is-open");
    wizard.setAttribute("aria-hidden", "true");
    document.body.classList.remove("no-scroll");
    document.documentElement.classList.remove("no-scroll");
  };

  // ---------- scoring (как в оригинале) ----------
  // major = позиция 0 (наиболее), minor = позиция 3 (наименее)
  const collectPayload = () => {
    const out = [];
    qsa(".disc-list", wizard).forEach((ul, listIndex) => {
      qsa("li", ul).forEach((li, idx) => out.push({ list: listIndex, pos: idx, type: li.dataset.type }));
    });
    return out;
  };
  const score = (payload) => {
    const maj = [], min = [];
    payload.forEach(x => { if (x.pos === 0) maj.push(x.type); if (x.pos === 3) min.push(x.type); });
    const count = (arr, ch) => arr.reduce((a, v) => a + (v === ch ? 1 : 0), 0);
    const r = {};
    TYPE_ORDER.forEach(t => { r[t] = count(maj, t) - count(min, t); });
    return r;
  };

  const showResult = (s) => {
    qs("#resultScore").textContent = "D:" + s.d + ", I:" + s.i + ", S:" + s.s + ", C:" + s.c;
    qs("#resultPage").classList.remove("hidden");
    qs("#startPage").classList.add("hidden");
  };

  // ---------- events ----------
  qs("#btnStart").addEventListener("click", () => {
    qs("#resultPage").classList.add("hidden");
    qs("#startPage").classList.remove("hidden");
    setStep(0);
    openWizard();
  });
  qsa("[data-disc-close]", wizard).forEach(x => x.addEventListener("click", closeWizard));
  document.addEventListener("keydown", (e) => { if (e.key === "Escape" && wizard.classList.contains("is-open")) closeWizard(); });
  tabs.forEach(t => t.addEventListener("click", () => setStep(Number(t.dataset.stepBtn))));
  btnPrev.addEventListener("click", () => setStep(step - 1));
  btnNext.addEventListener("click", () => setStep(step + 1));
  btnFinish.addEventListener("click", () => {
    const s = score(collectPayload());
    closeWizard();
    showResult(s);
  });
  qs("#btnRestart").addEventListener("click", () => {
    qs("#resultPage").classList.add("hidden");
    qs("#startPage").classList.remove("hidden");
    build(); initLists(); setStep(0); openWizard();
  });

  build();
  initLists();
  render();
})();
</script>
</body>
</html>
